+func (p *LaxPolygon) decode(d *decoder) {
+	*p = LaxPolygon{}
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("can't decode LaxPolygon version %d; expected %d", version, encodingVersion)
+		return
+	}
+	numLoops := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if numLoops > maxEncodedLoops {
+		d.err = fmt.Errorf("too many loops (%d; max is %d)", numLoops, maxEncodedLoops)
+		return
+	}
+	loops := make([][]Point, 0, min(numLoops, 1024))
+	var totalVertices uint64
+	for i := uint32(0); i < numLoops; i++ {
+		n := d.readUint32()
+		if d.err != nil {
+			return
+		}
+		if n > maxEncodedVertices {
+			d.err = fmt.Errorf("too many vertices in loop (%d; max is %d)", n, maxEncodedVertices)
+			return
+		}
+		totalVertices += uint64(n)
+		if totalVertices > maxEncodedVertices {
+			d.err = fmt.Errorf("too many vertices in polygon (%d; max is %d)", totalVertices, maxEncodedVertices)
+			return
+		}
+		pts := make([]Point, n)
+		for j := range pts {
+			pts[j].X = d.readFloat64()
+			pts[j].Y = d.readFloat64()
+			pts[j].Z = d.readFloat64()
+			if d.err != nil {
+				return
+			}
+		}
+		loops = append(loops, pts)
+	}
+	*p = *LaxPolygonFromPoints(loops)
+}
