+		shape := s.shapes[id]
+		if shape == nil {
+			e.err = fmt.Errorf("shape with ID %d is nil", id)
+			return
+		}
+		tag := shape.typeTag()
+		if tag == typeTagNone {
+			e.err = fmt.Errorf("cannot encode shape with typeTagNone (%T)", shape)
+			return
+		}
+		encodable, ok := shape.(encodableShape)
+		if !ok {
+			e.err = fmt.Errorf("shape %T does not implement encodableShape", shape)
+			return
+		}
+		e.writeInt32(id)
+		e.writeUint32(uint32(tag))
+		if e.err != nil {
+			return
+		}
+		if err := encodable.Encode(e.w); err != nil {
+			e.err = fmt.Errorf("failed to encode shape ID %d (%T): %w", id, shape, err)
+			return
+		}
+	}
