+	orig.Add(LaxPolygonFromPoints([][]Point{
+		parsePoints("0:0, 0:10, 10:10, 10:0"),
+		parsePoints("2:2, 2:5, 5:5, 5:2"),
+		[]Point{}, // full loop mixed in
+	}))
+
+	orig.Build()
+
+	var buf bytes.Buffer
+	if err := orig.Encode(&buf); err != nil {
+		t.Fatalf("Encode failed: %v", err)
+	}
+
+	dec := NewShapeIndex()
+	if err := dec.Decode(&buf); err != nil {
+		t.Fatalf("Decode failed: %v", err)
+	}
+
+	checkIndexesEqual(t, orig, dec)
+}
+
+func TestShapeIndexDecodeMalformedInput(t *testing.T) {
+	// 1. Nil reader
+	idx := NewShapeIndex()
+	if err := idx.Decode(nil); err == nil {
+		t.Fatalf("expected error decoding nil reader")
+	}
+
+	// 2. Empty stream
+	if err := idx.Decode(bytes.NewReader(nil)); err == nil {
+		t.Fatalf("expected error decoding empty stream")
+	}
+
+	// Create a valid index with multiple shapes and cells to test corruption and truncation
+	validIdx := NewShapeIndex()
+	validIdx.Add(makePolygon("0:0, 0:10, 10:10, 10:0", false))
+	validIdx.Add(makePolyline("20:20, 20:30, 30:30"))
+	validIdx.Add((*PointVector)(&[]Point{PointFromCoords(1, 0, 0)}))
+	validIdx.Build()
+
+	var validBuf bytes.Buffer
+	if err := validIdx.Encode(&validBuf); err != nil {
+		t.Fatalf("Encode failed: %v", err)
+	}
+	validBytes := validBuf.Bytes()
+
+	// 3. Truncated data at every byte boundary
+	t.Run("TruncatedBytes", func(t *testing.T) {
+		for k := 0; k < len(validBytes); k++ {
+			d := NewShapeIndex()
+			err := d.Decode(bytes.NewReader(validBytes[:k]))
+			if err == nil {
+				t.Fatalf("expected error decoding truncated data at length %d/%d", k, len(validBytes))
+			}
+		}
+	})
+
+	// 4. Corrupted version
+	t.Run("CorruptedVersion", func(t *testing.T) {
+		corrupted := append([]byte(nil), validBytes...)
+		corrupted[0] = 99 // invalid version
+		d := NewShapeIndex()
+		if err := d.Decode(bytes.NewReader(corrupted)); err == nil {
+			t.Fatalf("expected error decoding invalid version")
+		}
+	})
+
+	// 5. Oversized allocation requests
+	t.Run("OversizedNumShapes", func(t *testing.T) {
+		corrupted := append([]byte(nil), validBytes...)
+		// Header: [version: 1 byte][maxEdges: 4 bytes][nextID: 4 bytes][numShapes: 4 bytes]
+		// Overwrite numShapes at offset 9
+		binary.LittleEndian.PutUint32(corrupted[9:13], 0xFFFFFFFF)
+		d := NewShapeIndex()
+		if err := d.Decode(bytes.NewReader(corrupted)); err == nil {
+			t.Fatalf("expected error decoding oversized numShapes")
+		}
+	})
+
+	t.Run("OversizedNumCells", func(t *testing.T) {
+		// Create an empty index to know exact offsets
+		emptyIdx := NewShapeIndex()
+		var emptyBuf bytes.Buffer
+		emptyIdx.Encode(&emptyBuf)
+		emptyBytes := emptyBuf.Bytes()
+		// Header: version(1) + maxEdges(4) + nextID(4) + numShapes(4) = offset 13 is numCells
+		corrupted := append([]byte(nil), emptyBytes...)
+		binary.LittleEndian.PutUint32(corrupted[13:17], 0xFFFFFFFF)
+		d := NewShapeIndex()
+		if err := d.Decode(bytes.NewReader(corrupted)); err == nil {
+			t.Fatalf("expected error decoding oversized numCells")
+		}
+	})
+
+	// 6. Random corrupted bytes / bit flips fuzzing (must not panic)
+	t.Run("CorruptedBytesFuzz", func(t *testing.T) {
+		rng := rand.New(rand.NewSource(42))
+		for iter := 0; iter < 1000; iter++ {
+			corrupted := append([]byte(nil), validBytes...)
+			numCorruptions := 1 + rng.Intn(5)
+			for c := 0; c < numCorruptions; c++ {
+				pos := rng.Intn(len(corrupted))
+				corrupted[pos] ^= byte(1 + rng.Intn(255))
+			}
+			d := NewShapeIndex()
+			// Should return error or succeed, but NEVER panic
+			_ = d.Decode(bytes.NewReader(corrupted))
+		}
+	})
+}
+
+func TestShapeIndexSpatialQueriesWithoutBuild(t *testing.T) {
+	orig := NewShapeIndex()
+	// Add a polygon with a hole
+	poly := makePolygon("0:0, 0:20, 20:20, 20:0; 5:5, 5:15, 15:15, 15:5", false)
+	orig.Add(poly)
+	orig.Build()
+
+	var buf bytes.Buffer
+	if err := orig.Encode(&buf); err != nil {
+		t.Fatalf("Encode failed: %v", err)
+	}
+
+	dec := NewShapeIndex()
+	if err := dec.Decode(&buf); err != nil {
+		t.Fatalf("Decode failed: %v", err)
+	}
+
+	// 1. Point containment query without Build
+	query := NewContainsPointQuery(dec, VertexModelSemiOpen)
+	// Inside the polygon outer shell, outside the hole: (2, 2)
+	inPt := PointFromLatLng(LatLngFromDegrees(2, 2))
+	if !query.Contains(inPt) {
+		t.Fatalf("Contains(2, 2) expected true, got false")
+	}
+	// Inside the hole: (10, 10)
+	holePt := PointFromLatLng(LatLngFromDegrees(10, 10))
+	if query.Contains(holePt) {
+		t.Fatalf("Contains(10, 10) inside hole expected false, got true")
+	}
+	// Outside the polygon: (25, 25)
+	outPt := PointFromLatLng(LatLngFromDegrees(25, 25))
+	if query.Contains(outPt) {
+		t.Fatalf("Contains(25, 25) expected false, got true")
+	}
+
+	// 2. Iterator LocatePoint without Build
+	it := dec.Iterator()
+	if !it.LocatePoint(inPt) {
+		t.Fatalf("LocatePoint(2, 2) failed")
+	}
+	if it.Done() {
+		t.Fatalf("iterator should not be Done after LocatePoint")
+	}
+
+	// 3. ShapeIndexRegion bounds without Build
+	regOrig := orig.Region()
+	regDec := dec.Region()
+	if regOrig.CapBound() != regDec.CapBound() {
+		t.Fatalf("CapBound mismatch: orig=%v, dec=%v", regOrig.CapBound(), regDec.CapBound())
+	}
+	if regOrig.RectBound() != regDec.RectBound() {
+		t.Fatalf("RectBound mismatch: orig=%v, dec=%v", regOrig.RectBound(), regDec.RectBound())
+	}
+
+	// 4. LocateCellID without Build
+	targetCellID := cellIDFromPoint(inPt)
+	rel := dec.Iterator().LocateCellID(targetCellID)
+	if rel == Disjoint {
+		t.Fatalf("LocateCellID returned Disjoint for indexed point")
+	}
+}
+
+func TestShapeIndexMutateAfterDecode(t *testing.T) {
+	orig := NewShapeIndex()
+	orig.Add(makePolyline("0:0, 0:10"))
+	orig.Build()
+
+	var buf bytes.Buffer
+	if err := orig.Encode(&buf); err != nil {
+		t.Fatalf("Encode failed: %v", err)
+	}
+
+	dec := NewShapeIndex()
+	if err := dec.Decode(&buf); err != nil {
+		t.Fatalf("Decode failed: %v", err)
+	}
+
+	// Add a new shape to the decoded index
+	newID := dec.Add(makePolyline("20:20, 20:30"))
+	if newID != 1 {
+		t.Fatalf("expected newID = 1, got %d", newID)
+	}
+
+	// Now build the mutated index
+	dec.Build()
+
+	if dec.Len() != 2 {
+		t.Fatalf("expected Len = 2, got %d", dec.Len())
+	}
+	if dec.NumEdges() != 2 {
+		t.Fatalf("expected NumEdges = 2, got %d", dec.NumEdges())
+	}
+
+	// Both shapes should have cells now
+	edge0 := dec.Shape(0).Edge(0)
+	edge1 := dec.Shape(1).Edge(0)
+	q := NewCrossingEdgeQuery(dec)
+	if len(q.Crossings(edge0.V0, edge0.V1, dec.Shape(0), CrossingTypeAll)) == 0 {
+		t.Fatalf("failed to query edge 0 on mutated decoded index")
+	}
+	if len(q.Crossings(edge1.V0, edge1.V1, dec.Shape(1), CrossingTypeAll)) == 0 {
+		t.Fatalf("failed to query edge 1 on mutated decoded index")
+	}
+}
+
+func TestShapeIndexDecodeCorruptedSemantics(t *testing.T) {
+	validIdx := NewShapeIndex()
+	validIdx.Add(makePolyline("0:0, 0:10, 10:10"))
+	validIdx.Build()
+
+	var validBuf bytes.Buffer
+	if err := validIdx.Encode(&validBuf); err != nil {
+		t.Fatalf("Encode failed: %v", err)
+	}
+	validBytes := validBuf.Bytes()
+
+	// Corrupt maxEdgesPerCell to 0
+	t.Run("ZeroMaxEdges", func(t *testing.T) {
+		corrupted := append([]byte(nil), validBytes...)
+		binary.LittleEndian.PutUint32(corrupted[1:5], 0)
+		d := NewShapeIndex()
+		if err := d.Decode(bytes.NewReader(corrupted)); err == nil {
+			t.Fatalf("expected error for maxEdgesPerCell == 0")
+		}
+	})
+
+	// Corrupt nextID to negative
+	t.Run("NegativeNextID", func(t *testing.T) {
+		corrupted := append([]byte(nil), validBytes...)
+		binary.LittleEndian.PutUint32(corrupted[5:9], uint32(0xFFFFFFFF)) // -1
+		d := NewShapeIndex()
+		if err := d.Decode(bytes.NewReader(corrupted)); err == nil {
+			t.Fatalf("expected error for negative nextID")
+		}
+	})
+
+	// Corrupt shape typeTag to unknown
+	t.Run("UnknownShapeTypeTag", func(t *testing.T) {
+		corrupted := append([]byte(nil), validBytes...)
+		// Offset 13: shapeID (4 bytes), offset 17: typeTag (4 bytes)
+		binary.LittleEndian.PutUint32(corrupted[17:21], 9999)
+		d := NewShapeIndex()
+		if err := d.Decode(bytes.NewReader(corrupted)); err == nil {
+			t.Fatalf("expected error for unknown shape typeTag")
+		}
+	})
+}
